interface ProductosView {
  mostrarProductos(lista: Producto[]): void;
  mostrarError(mensaje: string): void;
  onBuscar(handler: (texto: string) => void): void;
}

class ProductosPresenter {
  constructor(private view: ProductosView, private api: CatalogoApi) {
    view.onBuscar((texto) => this.buscar(texto));
  }

  async buscar(texto: string) {
    if (texto.trim().length < 2) return this.view.mostrarError('Escribe al menos 2 letras');
    this.view.mostrarProductos(await this.api.buscar(texto));
  }
}

test('pide al menos 2 letras', async () => {
  const vista = { mostrarProductos: jest.fn(), mostrarError: jest.fn(), onBuscar: jest.fn() };
  const presenter = new ProductosPresenter(vista, apiFalsa);

  await presenter.buscar('p');

  expect(vista.mostrarError).toHaveBeenCalledWith('Escribe al menos 2 letras');
});

