export function useCarritoViewModel(api: CarritoApi) {
  const items = ref<Item[]>([]);
  const cupon = ref('');

  const total = computed(() =>
    items.value.reduce((s, i) => s + i.precio * i.cantidad, 0));

  async function aplicarCupon() {
    items.value = await api.aplicarCupon(cupon.value);
  }

  return { items, cupon, total, aplicarCupon };
}

